"""URL validation. See api/API.md."""
from urllib.parse import urlsplit

MAX_LEN = 2048


def is_valid_url(url) -> bool:
    if not isinstance(url, str) or not 1 <= len(url) <= MAX_LEN:
        return False
    if any(ord(c) < 33 or ord(c) == 127 for c in url):
        return False
    try:
        parts = urlsplit(url)
    except ValueError:
        return False
    return parts.scheme.lower() in ("http", "https") and bool(parts.hostname)
